import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.BZO4qERu.js";const u=JSON.parse('{"title":"Agents / ACP","description":"","frontmatter":{},"headers":[],"relativePath":"ru/guides/acp.md","filePath":"ru/guides/acp.md","lastUpdated":1792323081000}'),d={name:"ru/guides/acp.md"};function l(i,e,n,s,h,c){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="agents-acp" tabindex="-1">Agents / ACP <a class="header-anchor" href="#agents-acp" aria-label="Permalink to &quot;Agents / ACP&quot;">​</a></h1><p>Memoh может подключить Bot к ACP-совместимым агентам для программирования. ACP-агенты — это внешние рабочие процессы написания кода: они работают из чат-пространства Bot, но держат свои сессии отдельно от обычных разговоров chat и discuss.</p><p>В комплекте с Memoh идут два профиля агентов: <strong>Codex</strong> и <strong>Claude Code</strong>. Считайте их поддерживаемыми путями настройки, а не единственными возможными ACP-совместимыми агентами на будущее.</p><p>ACP-агенты выполняются внутри контейнерного рабочего пространства Bot, поэтому Bot должен использовать контейнерный бэкенд рабочего пространства.</p><hr><h2 id="порядок-настроики" tabindex="-1">Порядок настройки <a class="header-anchor" href="#порядок-настроики" aria-label="Permalink to &quot;Порядок настройки&quot;">​</a></h2><ol><li>Откройте страницу <strong>Detail Page</strong> нужного Bot и перейдите на вкладку <strong>Agents</strong>.</li><li>Каждый агент показан отдельной строкой с переключателем. Щёлкните по строке, чтобы открыть его настройки.</li><li>Выберите режим настройки и заполните поля, которые требует этот агент.</li><li>Сохраните, затем запустите включённого агента из чат-пространства.</li></ol><p>Строка показывает одно из трёх состояний: <strong>Needs setup</strong> (включён, но не хватает учётных данных), <strong>Disabled</strong> или зелёная точка (включён и готов).</p><h3 id="режимы-настроики-по-агентам" tabindex="-1">Режимы настройки по агентам <a class="header-anchor" href="#режимы-настроики-по-агентам" aria-label="Permalink to &quot;Режимы настройки по агентам&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Агент</th><th>API Key</th><th>OAuth</th><th>Self-managed</th></tr></thead><tbody><tr><td><strong>Codex</strong></td><td>✅</td><td>✅ вход через ChatGPT по коду устройства</td><td>✅</td></tr><tr><td><strong>Claude Code</strong></td><td>✅</td><td>✅ вставьте токен из <code>claude setup-token</code></td><td>✅</td></tr></tbody></table><p><strong>Self-managed</strong> означает, что Memoh запускает агента с конфигурацией, которую вы поддерживаете сами внутри рабочего пространства.</p><h3 id="авторизация-codex-по-коду-устроиства" tabindex="-1">Авторизация Codex по коду устройства <a class="header-anchor" href="#авторизация-codex-по-коду-устроиства" aria-label="Permalink to &quot;Авторизация Codex по коду устройства&quot;">​</a></h3><p>В настройках Codex нажмите <strong>Use Device Code</strong>. Memoh покажет URL подтверждения и одноразовый код пользователя, а после того как вы подтвердите его на странице OpenAI, авторизация завершится автоматически.</p><blockquote><p>Вводите код только на показанном URL подтверждения OpenAI — коды устройств могут использоваться для фишинга.</p></blockquote><h2 id="обновления-адаптеров" tabindex="-1">Обновления адаптеров <a class="header-anchor" href="#обновления-адаптеров" aria-label="Permalink to &quot;Обновления адаптеров&quot;">​</a></h2><p>Адаптеры Codex и Claude Code распространяются через npm. Memoh определяет последнюю опубликованную версию адаптера один раз за запуск сервера (для каждого Bot) и запускает именно её, поэтому исправления адаптеров приходят без обновления самого Memoh. Если поиск версии или запуск не удаётся, Memoh откатывается на версию адаптера из образа рабочего пространства — до следующего перезапуска сервера.</p><hr><h2 id="усилие-рассуждения" tabindex="-1">Усилие рассуждения <a class="header-anchor" href="#усилие-рассуждения" aria-label="Permalink to &quot;Усилие рассуждения&quot;">​</a></h2><p>Когда активный агент это поддерживает, вы можете выбирать усилие рассуждения для каждой сессии в селекторе моделей в поле ввода: наведите курсор на <strong>Reasoning</strong>, чтобы открыть список.</p><ul><li>Доступные варианты (и их названия) объявляет сам внешний агент; при смене модели они могут измениться.</li><li>Значения по умолчанию, пока вы ничего не выбрали: у Codex — <code>medium</code>, у Claude Code — <code>high</code>.</li><li>Выбор действует в рамках сессии и не зависит от выбора модели.</li></ul><p>Если ранее выбранное усилие становится недоступным, Memoh обновляет список вариантов агента и просит выбрать заново, а не отказывает молча.</p><hr><h2 id="вложения" tabindex="-1">Вложения <a class="header-anchor" href="#вложения" aria-label="Permalink to &quot;Вложения&quot;">​</a></h2><p>Сессии ACP-агентов поддерживают вложения в сообщениях:</p><ul><li><strong>Изображения</strong> отправляются нативно, если агент объявил поддержку ввода изображений. Иначе Memoh по возможности автоматически ссылается на изображение как на файл рабочего пространства.</li><li><strong>Файлы</strong>, длинный вставленный текст и вложения из цитируемых сообщений и ответов передаются агенту как пути рабочего пространства или публичные URL.</li><li>Можно отправить вложение вообще без текста.</li></ul><p>Если вложение не удаётся доставить агенту, Memoh сообщает в чате понятную ошибку, а не отбрасывает его молча.</p><hr><h2 id="агент-по-умолчанию" tabindex="-1">Агент по умолчанию <a class="header-anchor" href="#агент-по-умолчанию" aria-label="Permalink to &quot;Агент по умолчанию&quot;">​</a></h2><p>В настройках взаимодействия Bot можно выбрать <strong>Default Agent</strong> (агент по умолчанию) — сам Memoh или любой включённый и полностью настроенный ACP-агент. Выбор применяется только к новым сессиям один на один; существующие сессии и групповые разговоры discuss не затрагиваются.</p><hr><h2 id="сессии-acp-агентов" tabindex="-1">Сессии ACP-агентов <a class="header-anchor" href="#сессии-acp-агентов" aria-label="Permalink to &quot;Сессии ACP-агентов&quot;">​</a></h2><p>Работа через ACP использует тип сессии <code>acp_agent</code>. Такие сессии создаются и управляются рабочим процессом Agents/ACP, а не обычной маршрутизацией <code>/new chat</code> или <code>/new discuss</code>. В приложении можно отфильтровать сессии по <code>acp_agent</code>, чтобы смотреть работу агентов для программирования отдельно от повседневных разговоров.</p><hr><h2 id="связанные-страницы" tabindex="-1">Связанные страницы <a class="header-anchor" href="#связанные-страницы" aria-label="Permalink to &quot;Связанные страницы&quot;">​</a></h2><ul><li><a href="./working-with-bots.html">Работа с Bot</a></li><li><a href="./sessions.html">Сессии</a></li><li><a href="./files.html">Файлы</a></li><li><a href="./../integrations/providers/llm.html">Провайдеры и модели</a></li></ul>',35)])])}const g=t(d,[["render",l]]);export{u as __pageData,g as default};
